1,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981,981}}}
-- Shared controller; ASCII-only Lua strings, localized menu labels live in INI.
local followSystem=false
local manualWhite=false
local activeWhite=false
local nextThemeCheck=0
local themeMeasure=nil
local menuFollow,menuWhite=nil,nil

local function updateThemeMenu()
  local followLabel=followSystem and '#MenuFollowOn#' or '#MenuFollowOff#'
  local whiteLabel
  if followSystem then
    whiteLabel=activeWhite and '#MenuWhiteLockedOn#' or '#MenuWhiteLockedOff#'
  else
    whiteLabel=activeWhite and '#MenuWhiteOn#' or '#MenuWhiteOff#'
  end
  if menuFollow~=followLabel then
    SKIN:Bang('!SetOption','Rainmeter','ContextTitle',followLabel)
    menuFollow=followLabel
  end
  if menuWhite~=whiteLabel then
    SKIN:Bang('!SetOption','Rainmeter','ContextTitle2',whiteLabel)
    menuWhite=whiteLabel
  end
end

function ThemeReload()
  followSystem=SKIN:GetVariable('FollowSystem','1')=='1'
  manualWhite=SKIN:GetVariable('WhiteTheme','0')=='1'
  if followSystem then
    SKIN:Bang('!EnableMeasure','SystemTheme')
    nextThemeCheck=0
  else
    SKIN:Bang('!DisableMeasure','SystemTheme')
    activeWhite=manualWhite
  end
  updateThemeMenu()
end

function ThemeInitialize()
  themeMeasure=SKIN:GetMeasure('SystemTheme')
  ThemeReload()
  ThemeUpdate(os.clock())
end

function ThemeUpdate(now)
  if followSystem and now>=nextThemeCheck then
    SKIN:Bang('!UpdateMeasure','SystemTheme')
    -- Windows mode: 0 = dark, 1 = light. Match the user's chosen palette.
    activeWhite=themeMeasure:GetValue()==1
    nextThemeCheck=now+2
    updateThemeMenu()
  end
end

function ThemeIsWhite() return activeWhite end
function ThemeFollowsSystem() return followSystem end
function ThemeBodyColor() return activeWhite and '255,255,255' or '10,10,12' end
function ThemeEyeColor() return activeWhite and '10,10,12' or '255,255,255' end

local function saveThemeOption(key,value)
  value=tostring(value)
  SKIN:Bang('!WriteKeyValue','Variables',key,value,SKIN:GetVariable('@')..'Settings.inc')
  SKIN:Bang('!SetVariable',key,value)
  ThemeReload()
  ThemeUpdate(os.clock())
end

function ThemeToggleFollow()
  saveThemeOption('FollowSystem',followSystem and 0 or 1)
end

function ThemeToggleWhite()
  if followSystem then return end
  saveThemeOption('WhiteTheme',manualWhite and 0 or 1)
end

-- Optional pointer look; keep expression geometry and never introduce eyes.
local gazeEnabled=false
local gazeX,gazeY=nil,nil
local gaze={yaw=0,pitch=10,mix=0}
local renderedGaze={yaw=0,pitch=10,mix=0}
local gazeClock=nil

function GazeReload()
  gazeEnabled=SKIN:GetVariable('FollowMouse','0')=='1'
  for _,axis in ipairs({'MouseX','MouseY'}) do
    SKIN:Bang(gazeEnabled and '!EnableMeasure' or '!DisableMeasure',axis)
  end
  SKIN:Bang('!SetOption','Rainmeter','ContextTitle3',gazeEnabled and '#MenuMouseOn#' or '#MenuMouseOff#')
end

function GazeInitialize()
  gazeX=SKIN:GetMeasure('MouseX');gazeY=SKIN:GetMeasure('MouseY')
  gaze={yaw=0,pitch=10,mix=0};gazeClock=nil
  renderedGaze={yaw=0,pitch=10,mix=0}
  GazeReload()
end

function GazeToggle()
  local value=gazeEnabled and '0' or '1'
  SKIN:Bang('!WriteKeyValue','Variables','FollowMouse',value,SKIN:GetVariable('@')..'Settings.inc')
  SKIN:Bang('!SetVariable','FollowMouse',value)
  GazeReload()
end

function GazeCurrent() return renderedGaze end

function GazeUpdate(now,size,eligible,limits)
  local dt=gazeClock and math.max(0,now-gazeClock) or 0
  gazeClock=now
  if gazeEnabled then
    local cx=tonumber(SKIN:GetVariable('CURRENTCONFIGX','0'))+size/2
    local cy=tonumber(SKIN:GetVariable('CURRENTCONFIGY','0'))+size/2
    local nx=math.max(-1,math.min(1,(gazeX:GetValue()-cx)/400))
    local ny=math.max(-1,math.min(1,(gazeY:GetValue()-cy)/400))
    local a=1-math.exp(-dt/.10)
    gaze.yaw=gaze.yaw+(nx*16-gaze.yaw)*a
    local targetPitch=10-ny*(ny>0 and 16 or 13)
    gaze.pitch=gaze.pitch+(targetPitch-gaze.pitch)*a
  end
  -- Only an authored gaze action takes control; shape changes keep this weight.
  local target=gazeEnabled and eligible and 1 or 0
  local step=dt/.25
  gaze.mix=gaze.mix+math.max(-step,math.min(step,target-gaze.mix))
  renderedGaze={yaw=math.max(-limits.maxYaw,math.min(limits.maxYaw,gaze.yaw)),
    pitch=math.max(limits.minPitch,math.min(limits.maxPitch,gaze.pitch)),mix=gaze.mix}
  return renderedGaze
end

-- Geometry kernels adapted from bloub (MIT): shape.ts, engine.ts, face.ts.
local PI,TAU=math.pi,math.pi*2
local function clamp(x,a,b) return math.max(a or 0,math.min(b or 1,x)) end
local function lerp(a,b,t) return a+(b-a)*t end
local function ease(t) return 1-(1-clamp(t))^5 end
local function radius(profile,i)
  if type(profile)=='number' then return profile end
  return profile[i]
end
local function decode(id)
  local row=poseRows[id]
  local p={r=profiles[row[1]],n=row[25]==1}
  for i=2,29 do p[i]=row[i] end
  return p
end
local function blend(a,b,t)
  local p={r={}}
  for i=1,64 do p.r[i]=lerp(radius(a.r,i),radius(b.r,i),t) end
  for i=2,29 do p[i]=lerp(a[i],b[i],t) end
  local rot=b[2]-a[2]
  while rot>PI do rot=rot-TAU end
  while rot<-PI do rot=rot+TAU end
  p[2]=a[2]+rot*t
  local badge=t<.5 and a or b
  p.n=badge.n
  for i=26,29 do p[i]=badge[i] end
  return p
end
local function poseAt(style,t)
  local seq=style.seq
  local index=clamp(t*60,0,#seq-1)
  local i=math.floor(index)
  local a=decode(seq[i+1])
  if i>=#seq-1 or index==i then return a end
  return blend(a,decode(seq[i+2]),index-i)
end
local function noise(t,period,seed)
  local p=t/period*TAU
  return .55*math.sin(p+seed)+.3*math.sin(2*p+seed*1.7+1.1)+.15*math.sin(3*p+seed*2.3+2.4)
end
local function life(t,alive)
  local wander=alive and 1 or 0
  local lid=1
  local blinkTime=t%900
  for _,start in ipairs(blinks) do
    if blinkTime<start then break end
    local k=(blinkTime-start)/.18
    if k>=0 and k<=1 then lid=k<.45 and (1-k/.45) or ((k-.45)/.55); break end
  end
  return {
    yaw=(noise(t,11.3,.4)*5.5+noise(t,3.7,2.1)*1.6)*wander,
    pitch=(noise(t,9.1,1.3)*4.2+noise(t,4.3,.7)*1.3)*wander,
    roll=noise(t,13.7,3.2)*2.2*wander,
    lid=alive and lid or 1,
    dx=noise(t,7.9,1.9)*.006,dy=noise(t,5.3,.3)*.007,
    breath=1+math.sin(t/3.4*TAU)*.005
  }
end
local function spin(u,v,angle)
  local c,s=math.cos(angle*PI/180),math.sin(angle*PI/180)
  return {u[1]*c+v[1]*s,u[2]*c+v[2]*s,u[3]*c+v[3]*s},
         {v[1]*c-u[1]*s,v[2]*c-u[2]*s,v[3]*c-u[3]*s}
end
local function radialAt(profile,angle)
  if type(profile)=='number' then return profile end
  local t=(angle/TAU%1)*64
  local i=math.floor(t)
  return lerp(profile[i+1],profile[(i+1)%64+1],t-i)
end
local function xy(x,y) return string.format('%.4f,%.4f',x,y) end
local function closedPath(points)
  local n=#points
  local pieces={xy(points[1][1],points[1][2])}
  local svg={'M'..xy(points[1][1],points[1][2])}
  for i=1,n do
    local p0,p1,p2,p3=points[(i-2)%n+1],points[i],points[i%n+1],points[(i+1)%n+1]
    local c1x,c1y=p1[1]+(p2[1]-p0[1])/6,p1[2]+(p2[2]-p0[2])/6
    local c2x,c2y=p2[1]-(p3[1]-p1[1])/6,p2[2]-(p3[2]-p1[2])/6
    pieces[#pieces+1]='CurveTo '..xy(p2[1],p2[2])..','..xy(c1x,c1y)..','..xy(c2x,c2y)
    svg[#svg+1]='C'..xy(c1x,c1y)..','..xy(c2x,c2y)..','..xy(p2[1],p2[2])
  end
  pieces[#pieces+1]='ClosePath 1'
  svg[#svg+1]='Z'
  return table.concat(pieces,' | '),table.concat(svg)
end
local function capsule(w,h,m)
  local hw,hh=math.max(w,.01)/2,math.max(h,.01)/2
  local r=math.min(hw,hh)
  local k=.5522847498307936
  local function point(x,y)
    return xy(m[1]*x+m[3]*y+m[5],m[2]*x+m[4]*y+m[6])
  end
  local pieces={point(-hw,-hh+r)}
  local svg={'M'..point(-hw,-hh+r)}
  local function line(x,y) pieces[#pieces+1]='LineTo '..point(x,y);svg[#svg+1]='L'..point(x,y) end
  local function curve(x1,y1,x2,y2,x,y)
    pieces[#pieces+1]='CurveTo '..point(x,y)..','..point(x1,y1)..','..point(x2,y2)
    svg[#svg+1]='C'..point(x1,y1)..','..point(x2,y2)..','..point(x,y)
  end
  curve(-hw,-hh+r-k*r,-hw+r-k*r,-hh,-hw+r,-hh)
  line(hw-r,-hh)
  curve(hw-r+k*r,-hh,hw,-hh+r-k*r,hw,-hh+r)
  line(hw,hh-r)
  curve(hw,hh-r+k*r,hw-r+k*r,hh,hw-r,hh)
  line(-hw+r,hh)
  curve(-hw+r-k*r,hh,-hw,hh-r+k*r,-hw,hh-r)
  pieces[#pieces+1]='ClosePath 1';svg[#svg+1]='Z'
  return table.concat(pieces,' | '),table.concat(svg)
end
local function withLook(p,t,look)
  if not look or look.mix<=0 or p[21]<=.01 then return p end
  local q={r=p.r,n=p.n}
  for i=2,29 do q[i]=p[i] end
  local l=life(t,true)
  q[9]=lerp(p[9]+l.yaw,look.yaw,look.mix)-l.yaw
  q[10]=lerp(p[10]+l.pitch,look.pitch,look.mix)-l.pitch
  return q
end
local function geometry(p,t,size,forced,look)
  p=withLook(p,t,look)
  local l=life(t,p[21]>.01)
  local scale=size/360
  local R=100
  local center=size/2
  local dx,dy=p[7]+l.dx,p[8]+l.dy
  local cr,sr=math.cos(p[2]),math.sin(p[2])
  local pts={}
  for i=1,64 do
    local a=(i-1)/64*TAU
    local r=radius(p.r,i)
    local x,y=r*math.cos(a),r*math.sin(a)
    pts[i]={center+((x*cr-y*sr)*p[5]+p[3]+dx)*R*scale,
            center+((x*sr+y*cr)*p[6]*l.breath+p[4]+dy)*R*scale}
  end
  local body,bodySvg=closedPath(pts)
  local f,right,down={0,0,1},{1,0,0},{0,1,0}
  f,right=spin(f,right,p[9]+l.yaw)
  down,f=spin(down,f,p[10]+l.pitch)
  right,down=spin(right,down,p[11]+l.roll)
  local eyes={}
  for i=1,2 do
    local ef,er=spin(f,right,p[12]*(i==1 and -1 or 1))
    local at=i==1 and 13 or 17
    local phi=p[at+3]*PI/180
    local cp,sp=math.cos(phi),math.sin(phi)
    local lid=.06+.94*clamp(math.min(l.lid,forced or 1,p[at+2]))
    local x,y=ef[1]*R,ef[2]*R
    local fit=radialAt(p.r,math.atan2(y,x)-p[2])
    local m={(er[1]*cp+down[1]*sp)*scale,(er[2]*cp+down[2]*sp)*lid*scale,
      (-er[1]*sp+down[1]*cp)*scale,(-er[2]*sp+down[2]*cp)*lid*scale,
      center+(x*fit+(dx+p[23])*R)*scale,center+(y*fit+(dy+p[24])*R)*scale}
    local path,svg=capsule(p[at]*R,p[at+1]*R,m)
    eyes[i]={path=path,svg=svg,alpha=p[21]>.01 and ef[3]>.02 and p[21]*clamp(ef[3]/.12)*p[22] or 0}
  end
  local badge=nil
  if p.n then
    local fit=radialAt(p.r,math.atan2(p[27],p[26])-p[2])
    badge={x=center+(p[26]*fit+dx)*R*scale,y=center+(p[27]*fit+dy)*R*scale,
      r=p[28]*R*scale,notch=p[29]*R*scale}
  end
  return {body=body,svg=bodySvg,eyes=eyes,alpha=p[22],badge=badge}
end

local current,previous,originPose=1,nil,nil
local currentStart,previousStart,transitionStart=0,0,0
local currentPlan,previousPlan=nil,nil
local pool={}
local restRun=0
local restLimit=2
local shortRun=0
local dwellWeights={15,55,30}
local shortBurstGuard=true
local recent={}
local speed=1
local clockStart=0
local animationTime=0
local lastClock=nil
local ticks=0
local loadedNew,loadedOld='',''
local sampleNew,sampleOld=0,0
local lookLimits={maxYaw=16,minPitch=-6,maxPitch=23}
local originLimits=nil
local limitedLook={
  galet_triste={16,18},capsule_triste={16,12}
}

local function limitsFor(style)
  local bound=limitedLook[style.id]
  return {maxYaw=bound and bound[1] or 16,minPitch=-6,maxPitch=bound and bound[2] or 23}
end

local function blendLookLimits(a,b,k)
  local result={}
  for key,value in pairs(b) do
    -- Tighten early, release late as the body and eye shapes gain room.
    local phase=k
    if key~='minPitch' and value~=a[key] then phase=value>a[key] and k*k or 1-(1-k)^2 end
    result[key]=lerp(a[key],value,phase)
  end
  return result
end

local function blendedLimits(style,k)
  local target=limitsFor(style)
  if not originLimits or k>=1 then return target end
  return blendLookLimits(originLimits,target,k)
end

local function animationNow(now)
  -- Anchor playback to the first rendered update, not skin initialization.
  if lastClock==nil then lastClock=now;return animationTime end
  local dt=math.max(0,now-lastClock)
  lastClock=now
  -- Resume gently after a startup/render stall; do not skip a whole morph.
  if dt>.1 then dt=1/60 end
  animationTime=animationTime+dt
  return animationTime
end

local function randomSeconds(a,b) return math.random(a*1000,b*1000)/1000 end
local function loadDwellOptions()
  for i,key in ipairs({'ShortWeight','NormalWeight','LongWeight'}) do
    local value=tonumber(SKIN:GetVariable(key,tostring(({15,55,30})[i])))
    dwellWeights[i]=value and value==value and value<math.huge and math.max(0,value) or ({15,55,30})[i]
  end
  local total=dwellWeights[1]+dwellWeights[2]+dwellWeights[3]
  if total==0 then dwellWeights={15,55,30};total=100 end
  for i=1,3 do dwellWeights[i]=dwellWeights[i]/total end
  shortBurstGuard=SKIN:GetVariable('ShortBurstGuard','1')=='1'
end
local function dwell()
  local shortChance,normalChance=dwellWeights[1],dwellWeights[2]
  if shortBurstGuard and shortChance<1 then
    local reduced=shortRun>=2 and 0 or (shortRun==1 and shortChance/3 or shortChance)
    -- Move suppressed short weight to an enabled category only.
    if dwellWeights[3]==0 then normalChance=normalChance+shortChance-reduced end
    shortChance=reduced
  end
  local r=math.random()
  if r<shortChance then
    shortRun=shortRun+1
    return randomSeconds(2,4),'short'
  end
  shortRun=0
  if r<shortChance+normalChance then return randomSeconds(8,15),'normal' end
  return randomSeconds(20,35),'long'
end
local function planFor(style)
  if style.id=='exclaim' then
    return {total=style.base/60/speed,hold=0,pace='action'}
  elseif style.id=='alert' then
    local cycles=math.random(2,4)
    local join=.2
    return {total=(cycles*style.base/60+(cycles-1)*join)/speed,cycles=cycles,join=join,hold=0,pace='action'}
  end
  local hold,pace=dwell()
  if style.mode=='rest' then
    return {total=style.morph/speed+hold,hold=hold,pace=pace}
  elseif style.mode=='loop' then
    local cycles=math.random(2,3)*style.loopMultiplier
    local turn=(style.loopStart+cycles*style.loopPeriod)/speed
    local back=styles[1].morph/speed
    return {turn=turn,back=back,total=turn+back+hold,cycles=cycles,hold=hold,pace=pace}
  elseif style.mode=='return' then
    local turn=style.morph/speed+hold
    local back=styles[1].morph/speed
    return {turn=turn,back=back,total=turn+back+randomSeconds(2,4),hold=hold,pace=pace}
  end
  return {total=style.base/60/speed+hold,hold=hold,pace=pace}
end
local function playback(index,start,plan,now)
  local s=styles[index]
  local dt=math.max(0,now-start)
  local base=s.base/60
  local t=dt<base/speed and dt*speed or base+(dt-base/speed)
  local decoration=1
  if s.id=='exclaim' then
    t=math.min(dt*speed,base)
    return poseAt(s,t),t,1
  elseif s.id=='alert' then
    local authored=dt*speed
    local cycle=math.min(math.floor(authored/(base+plan.join)),plan.cycles-1)
    t=authored-cycle*(base+plan.join)
    if t>base and cycle<plan.cycles-1 then
      local k=clamp((t-base)/plan.join)
      k=k*k*(3-2*k)
      local a,b=poseAt(s,base),poseAt(s,0)
      -- The bar and its dot share horizontal travel; translate the sampled dot
      -- along the same true morph, without cutting or fading to a second dot.
      return blend(a,b,k),base,1,(b[3]-a[3])*k
    end
    t=math.min(t,base)
    return poseAt(s,t),t,1
  elseif s.mode=='loop' then
    if dt>=plan.turn then
      local k=ease((dt-plan.turn)/plan.back)
      return blend(poseAt(s,s.loopStart),poseAt(styles[1],0),k),s.loopStart,1-k
    end
    t=dt*speed
    if t>=s.loopStart then t=s.loopStart+(t-s.loopStart)%s.loopPeriod end
  elseif s.mode=='return' and dt>=plan.turn then
    local k=ease((dt-plan.turn)/plan.back)
    return blend(poseAt(s,base),poseAt(styles[1],0),k),base,1-k
  end
  return poseAt(s,t),t,decoration
end
local function composite(now)
  local b=playback(current,currentStart,currentPlan,now)
  local duration=styles[current].morph/speed
  local k=previous and ease((now-transitionStart)/duration) or 1
  if k>=1 then return b,1 end
  local a=originPose or playback(previous,previousStart,previousPlan,now)
  return blend(a,b,k),k
end

local function choose()
  if #pool==0 then for i=1,#styles do pool[i]=i end end
  local rests,actions=0,0
  for _,i in ipairs(pool) do if styles[i].kind=='rest' then rests=rests+1 else actions=actions+1 end end
  local weights,total={},0
  for j,i in ipairs(pool) do
    local s=styles[i]
    local eligible=s.kind=='rest' and restRun<restLimit and rests-1<=restLimit*actions+restLimit-1-restRun or s.kind=='action' and rests<=restLimit*actions
    local w=eligible and 1 or 0
    if i==current and #pool>1 then w=0 end
    for n,old in ipairs(recent) do
      if s.body==styles[old].body then w=w*(n==#recent and .015 or .3) end
      if s.kind=='rest' and styles[old].kind=='rest' and s.expression==styles[old].expression then w=w*.35 end
    end
    weights[j]=w;total=total+w
  end
  if total==0 then
    -- If similarity weights leave no candidate, retain the category limit.
    for j,i in ipairs(pool) do weights[j]=styles[i].kind=='action' and 1 or (restRun<restLimit and 1 or 0);total=total+weights[j] end
  end
  local r=math.random()*total
  local chosen=#pool
  for j,w in ipairs(weights) do r=r-w;if w>0 and r<=0 then chosen=j;break end end
  local index=table.remove(pool,chosen)
  restRun=styles[index].kind=='rest' and restRun+1 or 0
  recent[#recent+1]=index
  if #recent>3 then table.remove(recent,1) end
  return index
end

local function switch(now,index)
  local p,k=composite(now)
  -- Keep the raw morph origin; apply the same live look after pose interpolation.
  originPose=p
  originLimits=lookLimits
  previous,previousStart,previousPlan=current,currentStart,currentPlan
  current=index or choose()
  currentStart,transitionStart=now,now
  currentPlan=planFor(styles[current])
  loadedNew,loadedOld='',''
end

local options={}
local function set(name,key,value)
  value=tostring(value)
  local id=name..':'..key
  if options[id]~=value then SKIN:Bang('!SetOption',name,key,value);options[id]=value end
end
local function paint(g)
  local bodyAlpha=math.floor(clamp(g.alpha)*255+.5)
  set('Avatar','Body',g.body)
  set('Avatar','Shape2','Path Body | Fill Color '..ThemeBodyColor()..','..bodyAlpha..' | StrokeWidth 0')
  for i=1,2 do
    set('Avatar','Eye'..i,g.eyes[i].alpha>0 and g.eyes[i].path or '0,0 | LineTo 0,0 | ClosePath 1')
    local shape=i==1 and 'Shape3' or 'Shape5'
    set('Avatar',shape,'Path Eye'..i..' | Fill Color '..ThemeEyeColor()..','..math.floor(clamp(g.eyes[i].alpha)*255+.5)..' | StrokeWidth 0')
  end
  if g.badge then
    set('Avatar','Shape7','Ellipse '..xy(g.badge.x,g.badge.y)..','..g.badge.notch..' | Fill Color '..ThemeEyeColor()..','..bodyAlpha..' | StrokeWidth 0')
    set('Avatar','Shape9','Ellipse '..xy(g.badge.x,g.badge.y)..','..g.badge.r..' | Fill Color 36,150,232,255 | StrokeWidth 0')
  else
    set('Avatar','Shape7','Ellipse 0,0,0 | Fill Color 255,255,255,0 | StrokeWidth 0')
    set('Avatar','Shape9','Ellipse 0,0,0 | Fill Color 36,150,232,0 | StrokeWidth 0')
  end
end

local function paintDecor(prefix,index,t,alpha,size,shiftX)
  local s=styles[index]
  local frame=clamp(math.floor(t*60),0,#s.seq-1)
  local id=s.decor and (s.id..'_'..math.floor(frame/60)) or 'empty_0'
  local opacity=math.floor(clamp(alpha)*255+.5)
  local folder=s.themedDecor and ThemeIsWhite() and 'DecorWhite' or 'Decor'
  local marker=prefix=='New' and loadedNew or loadedOld
  local asset=folder..'\\'..id
  if opacity>0 and marker~=asset then
    for _,side in ipairs({'Back','Front'}) do set(side..prefix,'BitmapImage',SKIN:GetVariable('@')..asset..'_'..side..'.png') end
    if prefix=='New' then loadedNew=asset else loadedOld=asset end
  end
  local dx,dy=0,0
  if s.decor and opacity>0 then
    local sourceTime=frame/60
    dx=(noise((animationTime-clockStart)*speed,7.9,1.9)-noise(sourceTime,7.9,1.9))*.006*100*size/360
    dy=(noise((animationTime-clockStart)*speed,5.3,.3)-noise(sourceTime,5.3,.3))*.007*100*size/360
    dx=dx+(shiftX or 0)*100*size/360
  end
  for _,side in ipairs({'Back','Front'}) do
    set(side..prefix..'Mask','Shape','Rectangle 0,0,'..size..','..size..' | Fill Color 255,255,255,'..opacity..' | StrokeWidth 0')
    -- Meter X/Y parse as integers; matrix translation retains subpixel drift.
    set(side..prefix,'TransformationMatrix',string.format('%.9f;0;0;%.9f;%.9f;%.9f',size/200,size/200,dx,dy))
  end
  return frame%60
end

function Initialize()
  math.randomseed(os.time())
  speed=tonumber(SKIN:GetVariable('Speed','1'))
  clockStart=os.clock()
  animationTime=clockStart;lastClock=nil
  pool={};recent={};restRun=0
  shortRun=0
  loadDwellOptions()
  local rests,actions=0,0
  for _,s in ipairs(styles) do if s.kind=='rest' then rests=rests+1 else actions=actions+1 end end
  restLimit=math.max(2,math.ceil(rests/(actions+1)))
  current=choose();currentStart=clockStart
  previous=nil;originPose=nil;transitionStart=clockStart
  currentPlan=planFor(styles[current]);previousPlan=nil
  lookLimits=limitsFor(styles[current]);originLimits=nil
  loadedNew,loadedOld='',''
  options={}
  ticks=0
  ThemeInitialize()
  GazeInitialize()
end

function Update()
  local realNow=os.clock()
  ThemeUpdate(realNow)
  local now=animationNow(realNow)
  local size=tonumber(SKIN:GetVariable('Size','200'))
  if now-currentStart>=currentPlan.total then switch(now) end
  local p,k=composite(now)
  local forced=1
  if styles[current].blinkIn then
    local f=(now-transitionStart)*speed/.2
    if f<1 then forced=math.abs(f*2-1) end
  end
  local s=styles[current]
  local dt=now-currentStart
  -- Orbit owns its moving gaze. All other morphs, returns and invisible stages
  -- retain the pointer state so reappearing eyes already face the cursor.
  local follow=s.id~='orbit' or dt>=s.base/60/speed
  lookLimits=blendedLimits(s,k)
  local look=GazeUpdate(now,size,follow,lookLimits)
  paint(geometry(p,(now-clockStart)*speed,size,forced,look))
  local _,newTime,newDecor,newShift=playback(current,currentStart,currentPlan,now)
  sampleNew=paintDecor('New',current,newTime,k*newDecor,size,newShift)
  if previous and k<1 then
    local _,oldTime,oldDecor,oldShift=playback(previous,previousStart,previousPlan,now)
    sampleOld=paintDecor('Old',previous,oldTime,(1-k)*oldDecor,size,oldShift)
  else
    sampleOld=paintDecor('Old',current,0,0,size)
  end
  SKIN:Bang('!SetVariable','OldFrame',tostring(sampleOld))
  ticks=ticks+1
  return sampleNew
end

function Next()
  switch(animationNow(os.clock()))
  SKIN:Bang('!UpdateMeasure','Animation')
  SKIN:Bang('!UpdateMeter','Avatar')
  SKIN:Bang('!Redraw')
end

function Status()
  local now=animationTime
  local p,k=composite(now)
  return string.format('style=%s; mode=%s; remaining=%.2f; previous=%s; blend=%.6f; pool=%d; restRun=%d; updatesPerSecond=%.2f',styles[current].id,
    styles[current].mode,math.max(0,currentPlan.total-(now-currentStart)),previous and styles[previous].id or 'none',k,#pool,restRun,ticks/math.max(.001,os.clock()-clockStart))
end

-- Runtime diagnostics: return actual projected geometry for comparison to BotEngine.
local function probeSvg(g)
  local body=ThemeIsWhite() and 'white' or '#0a0a0c'
  local eye=ThemeIsWhite() and '#0a0a0c' or 'white'
  return '<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200"><defs><clipPath id="b"><path d="'..g.svg..'"/></clipPath></defs><path d="'..g.svg..'" fill="'..body..'" opacity="'..g.alpha..'"/><g clip-path="url(#b)"><path d="'..g.eyes[1].svg..'" fill="'..eye..'" opacity="'..g.eyes[1].alpha..'"/><path d="'..g.eyes[2].svg..'" fill="'..eye..'" opacity="'..g.eyes[2].alpha..'"/></g></svg>'
end

function Probe(index,t)
  return probeSvg(geometry(poseAt(styles[index],t),t,200,1))
end

function ProbeTransition(a,b,dt)
  local p=poseAt(styles[a],2.1+dt)
  local q=poseAt(styles[b],dt)
  return probeSvg(geometry(blend(p,q,ease(dt/styles[b].morph)),2.1+dt,200,1))
end

function CheckContinuity()
  local saved={current,previous,originPose,currentStart,previousStart,transitionStart,currentPlan,previousPlan,loadedNew,loadedOld,shortRun}
  local savedLimits,savedOriginLimits=lookLimits,originLimits
  current,previous,originPose=1,nil,nil
  currentStart=100
  currentPlan=planFor(styles[current])
  switch(102.1,26)
  local before=composite(102.2)
  switch(102.2,37)
  local after=composite(102.2)
  local maxError=0
  for i=1,64 do maxError=math.max(maxError,math.abs(radius(before.r,i)-radius(after.r,i))) end
  for i=2,24 do maxError=math.max(maxError,math.abs(before[i]-after[i])) end
  current,previous,originPose,currentStart,previousStart,transitionStart,currentPlan,previousPlan,loadedNew,loadedOld,shortRun=unpack(saved)
  lookLimits,originLimits=savedLimits,savedOriginLimits
  return string.format('interruptedMorphPoseError=%.9f',maxError)
end

function CheckOrder(rounds)
  local savedPool,savedRecent,savedRun,savedCurrent=pool,recent,restRun,current
  pool={};recent={};restRun=0
  local seen={};local maxRest=0;local repeats=0
  for i=1,rounds*#styles do
    local old=current
    local n=choose()
    current=n
    if (i-1)%#styles==0 then seen={} end
    if seen[n] then repeats=repeats+1 end
    seen[n]=true
    maxRest=math.max(maxRest,restRun)
  end
  pool,recent,restRun,current=savedPool,savedRecent,savedRun,savedCurrent
  return string.format('rounds=%d; repeatsInRound=%d; maximumConsecutiveRest=%d',rounds,repeats,maxRest)
end

function CheckMorph()
  local maxStartError,maxEndError=0,0
  for a=1,#styles do for b=1,#styles do if a~=b then
    local p,q=poseAt(styles[a],2.1),poseAt(styles[b],.3)
    local start,finish=blend(p,q,ease(0)),blend(p,q,ease(1))
    for i=1,64 do
      maxStartError=math.max(maxStartError,math.abs(radius(start.r,i)-radius(p.r,i)))
      maxEndError=math.max(maxEndError,math.abs(radius(finish.r,i)-radius(q.r,i)))
    end
  end end end
  return string.format('pairs=%d; startRadiusError=%.9f; endRadiusError=%.9f',#styles*(#styles-1),maxStartError,maxEndError)
end
